# Use document-relative paths so GitHub project URLs work with any repository name.
import os
for page in dist.rglob('*.html'):
 def portable_link(match):
  attr,path=match.groups()
  if path.startswith('//'):return match.group(0)
  suffix=''
  for marker in ['?', '#']:
   if marker in path:
    path,tail=path.split(marker,1);suffix=marker+tail;break
  relative=os.path.relpath(dist / (path.lstrip('/') or 'index.html'),page.parent).replace(os.sep,'/')
  return attr+'="'+relative+suffix+'"'
 page.write_text(re.sub(r'(href|src|data-full)="(/[^"\s]*)"',portable_link,page.read_text()))
js_path=dist/'assets/site.js'
js_path.write_text(js_path.read_text().replace("a.getAttribute('href')===location.pathname","new URL(a.getAttribute('href'),location.href).pathname===location.pathname"))
